use vstd::prelude::*;

verus! {

    /// Interleave three equally‐long i32‐vectors:
    /// produces [ s1[0], s2[0], s3[0],  s1[1], s2[1], s3[1],  … ].
    fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>)
        -> (res: Vec<i32>)
        requires
            // all three inputs have the same length n
            s1.len() == s2.len(),
            s2.len() == s3.len(),
            // 3⋅n fits in an i32
            (s1.len() as i64) * 3 <= i32::MAX as i64,
        ensures
            // the result has length exactly 3⋅n
            res.len() == 3 * s1.len(),
            // and for every index j in [0,n):
            //   res[3*j]   == s1[j]
            //   res[3*j+1] == s2[j]
            //   res[3*j+2] == s3[j]
            forall |j: usize| j < s1.len() ==>
                *res.index(3*j)   == *s1.index(j) &&
                *res.index(3*j+1) == *s2.index(j) &&
                *res.index(3*j+2) == *s3.index(j),
    {
        let n = s1.len();
        // build an empty Vec and reserve 3⋅n slots up‐front
        let mut res: Vec<i32> = Vec::new();
        res.reserve(3 * n);

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                res.len() == 3 * i,
                // for each completed index j < i, we have already interleaved
                forall |j: usize| j < i ==>
                    *res.index(3*j)   == *s1.index(j) &&
                    *res.index(3*j+1) == *s2.index(j) &&
                    *res.index(3*j+2) == *s3.index(j),
                // the capacity‐assumption remains
                (s1.len() as i64) * 3 <= i32::MAX as i64,
            decreases n - i,
        {
            // fetch the three elements at position i
            let x1 = *s1.index(i);
            let x2 = *s2.index(i);
            let x3 = *s3.index(i);
            // append them in order
            res.push(x1);
            res.push(x2);
            res.push(x3);
            i += 1;
        }

        res
    }

} // end verus!

